styles:
:root{
    --ink:#234E48;
    --ink-soft:#5C7C75;
    --cream:#E9F1E9;
    --cream2:#DCE9E1;
    --coral:#4F9E8E;
    --coral-d:#3B8375;
    --amber:#B79A63;
    --peach:#E3EFE7;
    --white:#ffffff;
    --line:rgba(35,78,72,.14);
    --fire:linear-gradient(100deg,#4F9E8E,#7FC0AF);
    --display:var(--font-archivo),-apple-system,sans-serif;
    --serif:var(--font-display),Georgia,serif;
    --sans:var(--font-sans),-apple-system,sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  .vh{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
  html{scroll-behavior:smooth}
  section[id]{scroll-margin-top:80px}
  body{font-family:var(--sans);background:linear-gradient(180deg,#FAFDF9 0%,#F2F8F1 26%,#F5FAF4 52%,#F0F7EF 80%,#F7FBF6 100%);background-attachment:fixed;color:var(--ink);line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:clip}
  h1,h2,h3{font-family:var(--display);font-weight:900;line-height:.98;letter-spacing:-.02em;text-transform:uppercase}
  .historia h2,.servicios .serv-head h2,.testimonios h2,.faq h2,.invita h2{text-transform:none;letter-spacing:-.015em;line-height:1.06}
  em{font-family:var(--serif);font-style:italic;font-weight:400;text-transform:none;letter-spacing:0}
  a{color:inherit;text-decoration:none}
  img{max-width:100%;display:block}
  ::selection{background:var(--coral);color:var(--white)}
  .wrap{max-width:1160px;margin:0 auto;padding:0 clamp(1.3rem,5vw,3.4rem)}
  .sec{padding:clamp(2.8rem,5.5vw,4.6rem) 0}
  .sec-line{width:min(1100px,86%);height:1px;margin:0 auto;background:linear-gradient(90deg,transparent,rgba(35,78,72,.2) 22%,rgba(35,78,72,.2) 78%,transparent)}

  .eyebrow{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-size:.74rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--coral-d);margin-bottom:22px}
  .eyebrow::before{content:"";width:30px;height:3px;background:var(--fire);border-radius:3px}
  .eyebrow.no-line::before{display:none}

  .btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-size:.82rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;padding:17px 34px;border-radius:10px;cursor:pointer;border:2px solid transparent;transition:transform .25s ease,box-shadow .25s ease,background .25s ease,color .25s ease}
  .btn .arw{transition:transform .25s ease}
  .btn:hover .arw{transform:translateX(5px)}
  .btn-fire{background:var(--coral);color:#fff;box-shadow:0 10px 26px rgba(79,158,142,.30)}
  .offer-body .btn-fire{background:#1E6A64;box-shadow:0 12px 28px rgba(30,106,100,.32)}
  .offer-body .btn-fire:hover{background:#175752}
  .btn-fire:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(79,158,142,.40)}
  .btn-ghost{background:transparent;color:var(--ink);border-color:var(--ink)}
  .btn-ghost:hover{background:var(--ink);color:var(--cream)}
  .btn-lg{font-size:1.02rem;padding:23px 56px}
  @keyframes pulseBeat{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
  .btn-pulse{animation:pulseBeat 1.7s ease-in-out infinite}
  .btn-pulse:hover{animation-play-state:paused}
  @media(prefers-reduced-motion:reduce){.btn-pulse{animation:none}}
  .microcopy{font-size:.78rem;color:var(--ink-soft);margin-top:14px;letter-spacing:.02em}

  /* photo placeholder */
  .photo-ph{background:linear-gradient(150deg,var(--peach),var(--cream2));border:2px dashed rgba(79,158,142,.4);border-radius:16px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--coral-d);padding:28px;min-height:340px}
  .photo-ph .ico{font-size:1.6rem;margin-bottom:10px}
  .photo-ph strong{font-family:var(--serif);font-style:italic;font-weight:400;font-size:1.05rem;display:block;margin-bottom:6px;color:var(--ink)}
  .photo-ph span{font-size:.78rem;color:var(--ink-soft);max-width:240px}
  .photo-real{display:block;width:100%;height:100%;object-fit:cover;border-radius:20px;box-shadow:0 18px 50px rgba(35,78,72,.22)}
  .hero-photo .photo-real{min-height:clamp(400px,62vh,580px);object-position:center 25%;border-radius:6px;position:relative;z-index:1}
  .historia .photo-frame{border-radius:0;overflow:visible;box-shadow:none;background:transparent}
  .historia .photo-frame img{display:block;width:100%;height:auto;border-radius:0;filter:drop-shadow(0 14px 30px rgba(35,78,72,.16))}

  /* NAV */
  nav{position:fixed;top:0;left:0;right:0;z-index:100;display:flex;justify-content:space-between;align-items:center;padding:1rem clamp(1.3rem,5vw,3.4rem);background:rgba(240,246,239,.82);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
  nav .logo{font-family:var(--display);font-weight:800;font-size:1.05rem;letter-spacing:.02em;text-transform:uppercase}
  nav .logo em{color:var(--coral)}
  nav .nav-links{display:flex;gap:1.8rem;align-items:center}
  nav .nav-links a{font-family:var(--display);font-size:.74rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;transition:color .25s}
  nav .nav-links a:hover{color:var(--coral)}
  nav .nav-cta{background:var(--coral);color:var(--white)!important;padding:9px 18px;border-radius:7px}
  nav .nav-cta:hover{background:var(--coral-d)}
  @media(max-width:840px){nav .nav-links a:not(.nav-cta){display:none}}

  /* HERO */
  .hero{position:relative;min-height:100vh;display:grid;grid-template-columns:1.08fr .8fr;align-items:center;gap:clamp(2.4rem,4.5vw,4.6rem);padding-top:6rem;max-width:1340px;overflow:hidden}
  .hero-map{position:absolute;inset:0;z-index:0;pointer-events:none;overflow:hidden;-webkit-mask-image:linear-gradient(180deg,#000 0%,#000 42%,rgba(0,0,0,.45) 68%,transparent 90%);mask-image:linear-gradient(180deg,#000 0%,#000 42%,rgba(0,0,0,.45) 68%,transparent 90%)}
  .hero-map svg{position:absolute;inset:0;width:100%;height:100%;color:var(--coral-d)}
  .hero-map .hm-land{fill:currentColor;fill-opacity:.055;stroke:none}
  .hero-map .hm-ruta{fill:none;stroke:currentColor;stroke-opacity:.18;stroke-width:2;stroke-dasharray:2 13;stroke-linecap:round;vector-effect:non-scaling-stroke}
  .hero-map .hm-pin{fill:currentColor;fill-opacity:.18}
  .hero-map .hm-avion path{fill:currentColor;fill-opacity:.22}
  @media(max-width:900px){.hero-map .hm-land{fill-opacity:.045}}
  .hero-copy{position:relative;z-index:2}
  .hero .welcome{font-family:var(--display);font-weight:700;text-transform:uppercase;letter-spacing:.12em;font-size:clamp(.95rem,1.4vw,1.1rem);color:var(--ink-soft);margin-bottom:20px}
  .hero h1{font-size:clamp(3.6rem,10.2vw,7.5rem);margin-bottom:26px;line-height:1.18}
  .hero h1 .fire-word{background:var(--fire);-webkit-background-clip:text;background-clip:text;color:transparent}
  .globe-o{display:inline-block;height:1.05em;vertical-align:-.055em;margin:0 0 0 .05em}
  .globe-o .globe-img{height:100%;width:auto;display:block}
  .globe-o svg{width:100%;height:100%;display:block}
  .hero-frase{font-size:clamp(1.3rem,2.1vw,1.65rem);line-height:1.4;color:var(--ink-soft);max-width:34ch;margin-bottom:0;font-weight:400}
  .hero-frase b{color:var(--ink);font-weight:700}
  .hero-frase em{display:inline-block;margin-top:8px;font-family:var(--serif);font-style:italic;font-weight:400;font-size:1.12em;line-height:1.35;color:var(--coral-d)}
  .hero-btns{display:flex;gap:14px;flex-wrap:wrap}
  .hero-btns .btn{font-size:1rem;padding:21px 46px}
  .hero-photo{position:relative;z-index:2;margin-left:clamp(0px,3.5vw,52px)}
  .hero-photo::before{content:"";position:absolute;inset:-13px;border-radius:16px;background:rgba(252,253,251,.6);box-shadow:0 22px 55px rgba(35,78,72,.12);z-index:0;pointer-events:none}
  .hero-photo .photo-ph{min-height:clamp(400px,62vh,580px);border-radius:20px}
  @media(max-width:840px){.hero{grid-template-columns:1fr;min-height:auto;padding-top:7rem;text-align:center}.hero-copy{order:2}.hero-photo{order:1;margin-left:0}.hero-frase{margin-inline:auto}.eyebrow,.hero-btns{justify-content:center}}

  /* MARQUEE */
  .marquee{background:var(--coral);color:#F7FBF6;padding:18px 0;overflow:hidden;white-space:nowrap}
  .marquee-track{display:inline-flex;gap:0;animation:slide 22s linear infinite}
  .marquee span{font-family:var(--display);font-weight:800;text-transform:uppercase;letter-spacing:.05em;font-size:1.05rem;padding:0 26px;display:inline-flex;align-items:center;gap:26px}
  .marquee span::after{content:"✦";color:#E9F1E9;font-size:.7rem}
  @keyframes slide{from{transform:translateX(0)}to{transform:translateX(-50%)}}
  @media(prefers-reduced-motion:reduce){.marquee-track{animation:none}}

  /* HISTORIA */
  .historia{background:transparent}
  .historia .grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(2rem,5vw,4.5rem);align-items:center}
  .historia h2{font-size:clamp(2.2rem,5vw,3.6rem);margin-bottom:24px}
  .historia h2 em{color:var(--coral)}
  .historia p{color:var(--ink-soft);font-size:clamp(1.02rem,1.25vw,1.18rem);line-height:1.6;margin-bottom:14px;max-width:52ch;font-weight:400}
  .historia .sign{font-family:var(--serif);font-style:italic;font-size:1.6rem;color:var(--coral);margin-top:10px}
  .historia .stats{display:flex;gap:clamp(2rem,5vw,3.6rem);margin-top:26px;padding-top:24px;border-top:1px solid rgba(79,158,142,.22);flex-wrap:wrap}
  .historia .stats .stat .num{font-family:var(--display);font-weight:900;font-size:clamp(2.1rem,4vw,2.9rem);line-height:1;color:var(--coral)}
  .historia .stats .stat .num small{font-family:var(--serif);font-style:italic;font-weight:400;font-size:.62em}
  .historia .stats .stat .lbl{margin-top:8px;font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-soft);font-weight:600}
  @media(max-width:840px){.historia .stats{justify-content:center;text-align:center}}
  @media(max-width:840px){.historia .grid{grid-template-columns:1fr}}

  /* REGALO */
  .regalo{background:transparent;color:var(--ink)}
  .regalo-card{position:relative;overflow:hidden;max-width:720px;margin:0 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:clamp(470px,55vw,570px);border:3px solid rgba(255,255,255,.92);border-radius:30px;padding:clamp(2.8rem,5vw,4rem);background:linear-gradient(rgba(222,235,226,.5),rgba(222,235,226,.5)),url("/legacy-assets/3a4fbc567070b759.jpg") center/auto 102% no-repeat,#E9F1E9;box-shadow:0 26px 56px rgba(35,78,72,.2);animation:regalofloat 6s ease-in-out infinite alternate}
  .regalo-spark{position:absolute;z-index:3;pointer-events:none;line-height:1;color:#fff;text-shadow:0 0 8px rgba(255,255,255,.9),0 0 3px rgba(255,255,255,.7)}
  .regalo-spark.s1{top:8%;left:8%;font-size:1.1rem;animation:regalotwinkle 3.8s ease-in-out 0s infinite}
  .regalo-spark.s2{top:14%;right:10%;font-size:.8rem;animation:regalotwinkle 3.8s ease-in-out .6s infinite}
  .regalo-spark.s3{top:44%;left:5%;font-size:.95rem;animation:regalotwinkle 3.8s ease-in-out 1.2s infinite}
  .regalo-spark.s4{top:55%;right:6%;font-size:1.25rem;animation:regalotwinkle 3.8s ease-in-out 1.8s infinite}
  .regalo-spark.s5{bottom:10%;left:11%;font-size:.8rem;animation:regalotwinkle 3.8s ease-in-out 2.4s infinite}
  .regalo-spark.s6{bottom:8%;right:13%;font-size:1.05rem;animation:regalotwinkle 3.8s ease-in-out 3s infinite}
  .regalo-card .eyebrow{color:var(--coral-d)}
  .regalo-card .eyebrow::before{background:var(--coral-d)}
  .regalo-card h2{font-family:var(--serif);font-style:normal;font-weight:500;text-transform:none;letter-spacing:.004em;line-height:1.2;font-size:clamp(1.85rem,4vw,2.78rem);margin-bottom:18px;color:var(--ink)}
  .regalo-card{max-width:772px;padding:clamp(2.6rem,4.5vw,3.6rem) clamp(1.5rem,2.6vw,2.2rem)}
  @media(min-width:600px){.regalo-card h2 em{white-space:nowrap}}
  .regalo-card h2 em{color:var(--coral-d)}
  .regalo-card p{color:var(--ink);max-width:44ch;margin:0 auto 30px;font-weight:500}
  .regalo .btn-fire{background:var(--coral);color:#fff;box-shadow:0 14px 32px rgba(35,78,72,.34)}
  .regalo .btn-fire:hover{background:var(--coral-d);color:#fff}
  @keyframes regalofloat{from{transform:translateY(0)}to{transform:translateY(-12px)}}
  @keyframes regalotwinkle{0%,100%{opacity:.25}50%{opacity:.95}}

  .regalo-spark{display:none}
  .regalo-card{background:linear-gradient(160deg,#F7FBF6,#EDF4EC)!important;box-shadow:0 14px 38px rgba(35,78,72,.12)!important;border:1px solid rgba(255,255,255,.9)!important;animation:none!important;min-height:auto!important}
  /* PROCESO */
  .proceso h2{font-size:clamp(2.2rem,5vw,3.4rem);text-align:center;margin-bottom:12px}
  .proceso h2 em{color:var(--coral)}
  .proceso .lead{text-align:center;color:var(--ink-soft);max-width:48ch;margin:0 auto 58px;font-weight:400}
  .pasos{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
  .paso{background:rgba(255,255,255,.4);border:1px solid rgba(79,158,142,.15);border-radius:16px;padding:38px 30px;transition:transform .3s ease,box-shadow .3s ease}
  .carousel .paso .tema-ico svg{width:30px;height:30px;color:var(--coral);display:block}
  .paso:hover{transform:translateY(-6px);box-shadow:0 22px 44px rgba(35,78,72,.12)}
  .paso .num{font-family:var(--display);font-weight:900;font-size:2.4rem;background:var(--fire);-webkit-background-clip:text;background-clip:text;color:transparent;display:block;margin-bottom:12px;line-height:1}
  .tema-ico{font-size:2rem;display:block;margin-bottom:12px;line-height:1}
  /* ----- carrusel de temas ----- */
  .carousel{overflow:hidden;position:relative}
  .carousel-track{display:flex;gap:24px;will-change:transform}
  .carousel .paso{flex:0 0 calc((100% - 48px)/3);box-sizing:border-box;text-align:center;padding:40px 30px 34px;background:#fff;border:1px solid #DCE9E1;border-radius:18px;box-shadow:0 14px 34px rgba(35,78,72,.07)}
  .carousel .paso .tema-ico{width:64px;height:64px;border-radius:50%;background:linear-gradient(160deg,#E7F1E9,#CFE3D6);box-shadow:0 8px 18px rgba(35,78,72,.16);display:flex;align-items:center;justify-content:center;margin:0 auto 22px;font-size:0}
  .carousel .paso h3{font-family:var(--display);font-weight:800;text-transform:uppercase;letter-spacing:.02em;font-size:1.3rem;margin-bottom:14px;line-height:1.2;color:var(--coral-d);position:relative;padding-bottom:13px}
  .carousel .paso h3::after{content:"";position:absolute;left:50%;bottom:0;transform:translateX(-50%);width:32px;height:2px;background:var(--coral);border-radius:2px}
  .carousel .paso p{font-size:.94rem;line-height:1.5;color:var(--ink-soft)}
  .carousel-ctrl{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:34px}
  .carousel-arrow{width:46px;height:46px;border-radius:50%;border:1.6px solid var(--coral);background:transparent;color:var(--coral);font-size:1.5rem;line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .25s ease}
  .carousel-arrow:hover{background:var(--coral);color:#fff;transform:translateY(-1px)}
  .carousel-dots{display:flex;gap:8px;justify-content:center}
  .carousel-dots button{width:8px;height:8px;padding:0;border:none;border-radius:50%;background:var(--line);cursor:pointer;transition:all .3s ease}
  .carousel-dots button.active{background:var(--coral);width:24px;border-radius:5px}
  @media(max-width:840px){.carousel .paso{flex:0 0 100%}}
  .paso h3{font-size:1.3rem;margin-bottom:10px;text-transform:none;letter-spacing:-.01em}
  .paso p{color:var(--ink-soft);font-size:.95rem;font-weight:400}
  @media(max-width:840px){.pasos{grid-template-columns:1fr}}

  /* SESIONES */
  .sesiones{background-color:var(--cream2);background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22380%22%20height%3D%22380%22%20viewBox%3D%220%200%20380%20380%22%20fill%3D%22none%22%20stroke%3D%22%237a2f3f%22%20stroke-width%3D%221.0%22%20stroke-opacity%3D%220.12%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cg%20transform%3D%22translate%2872%2C84%29%20rotate%28-16%29%20scale%280.85%29%22%3E%3Cpath%20d%3D%22M0%2C-13%20C1%2C-13%201.6%2C-9%201.7%2C-5%20L2.4%2C-1%20L13%2C4%20L13%2C6%20L2.4%2C2%20L2.5%2C8%20L6%2C11%20L6%2C12.5%20L2%2C11%20L1.8%2C13%20C1.3%2C14.5%20-1.3%2C14.5%20-1.8%2C13%20L-2%2C11%20L-6%2C12.5%20L-6%2C11%20L-2.5%2C8%20L-2.4%2C2%20L-13%2C6%20L-13%2C4%20L-2.4%2C-1%20L-1.7%2C-5%20C-1.6%2C-9%20-1%2C-13%200%2C-13%20Z%22%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%22M44%2096%20q%2022%20-16%2050%20-6%22%20stroke-dasharray%3D%221.3%207%22%2F%3E%3Cg%20transform%3D%22translate%28258%2C128%29%20rotate%2822%29%20scale%280.85%29%22%3E%3Cpath%20d%3D%22M0%2C-13%20C1%2C-13%201.6%2C-9%201.7%2C-5%20L2.4%2C-1%20L13%2C4%20L13%2C6%20L2.4%2C2%20L2.5%2C8%20L6%2C11%20L6%2C12.5%20L2%2C11%20L1.8%2C13%20C1.3%2C14.5%20-1.3%2C14.5%20-1.8%2C13%20L-2%2C11%20L-6%2C12.5%20L-6%2C11%20L-2.5%2C8%20L-2.4%2C2%20L-13%2C6%20L-13%2C4%20L-2.4%2C-1%20L-1.7%2C-5%20C-1.6%2C-9%20-1%2C-13%200%2C-13%20Z%22%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%22M232%20142%20q%2024%20-15%2052%20-4%22%20stroke-dasharray%3D%221.3%207%22%2F%3E%3Cg%20transform%3D%22translate%28146%2C256%29%20rotate%28-8%29%20scale%280.85%29%22%3E%3Cpath%20d%3D%22M0%2C-13%20C1%2C-13%201.6%2C-9%201.7%2C-5%20L2.4%2C-1%20L13%2C4%20L13%2C6%20L2.4%2C2%20L2.5%2C8%20L6%2C11%20L6%2C12.5%20L2%2C11%20L1.8%2C13%20C1.3%2C14.5%20-1.3%2C14.5%20-1.8%2C13%20L-2%2C11%20L-6%2C12.5%20L-6%2C11%20L-2.5%2C8%20L-2.4%2C2%20L-13%2C6%20L-13%2C4%20L-2.4%2C-1%20L-1.7%2C-5%20C-1.6%2C-9%20-1%2C-13%200%2C-13%20Z%22%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%22M120%20268%20q%2022%20-15%2050%20-5%22%20stroke-dasharray%3D%22