  .sesiones-head{max-width:660px;margin-bottom:52px}
  .sesiones-head h2{font-size:clamp(2.2rem,5vw,3.4rem)}
  .sesiones-head h2 em{color:var(--coral)}
  .sesiones-head p{color:var(--ink-soft);margin-top:18px;font-weight:400}
  .ses-intro{display:grid;grid-template-columns:1.18fr .82fr;gap:clamp(34px,4.5vw,60px);align-items:center;max-width:1080px;margin:0 auto clamp(48px,5vw,68px);text-align:left}
  .ses-head h2{font-size:clamp(2.1rem,4.4vw,3.05rem);line-height:1.06}
  @media(min-width:841px){.ses-head h2 .nl,.regalo-card h2 .nl{white-space:nowrap}}
  .ses-head h2 em{color:var(--coral)}
  .ses-head .eyebrow{justify-content:flex-start;font-size:1rem;letter-spacing:.16em;margin-bottom:18px}
  .ses-head p{color:var(--ink-soft);margin-top:18px;font-weight:400;line-height:1.6}
  .ses-photo{margin:0;position:relative}
  .ses-photo img{display:block;width:100%;height:clamp(380px,42vw,490px);object-fit:cover;object-position:center 18%;border-radius:200px 200px 28px 28px;border:4px solid #F7FBF6;box-shadow:0 24px 50px rgba(35,78,72,.2)}
  .ses-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0;max-width:1000px;margin:0 auto 46px}
  .ses-card{background:none;border:0;border-radius:0;box-shadow:none;padding:12px 40px;text-align:center;position:relative}
  .ses-card:hover{transform:none}
  .ses-card + .ses-card::before{content:"";position:absolute;left:0;top:6%;bottom:6%;width:1px;background:linear-gradient(180deg,rgba(79,158,142,0),rgba(79,158,142,.26) 18%,rgba(79,158,142,.26) 82%,rgba(79,158,142,0))}
  .ses-card .ico{width:64px;height:64px;border-radius:50%;background:linear-gradient(160deg,#E7F1E9,#CFE3D6);box-shadow:0 8px 18px rgba(35,78,72,.16);display:flex;align-items:center;justify-content:center;margin:0 auto 22px}
  .ses-card .ico svg{width:30px;height:30px;color:var(--coral);display:block}
  .ses-card h3{font-family:var(--display);font-weight:800;font-size:1.3rem;color:var(--coral-d);margin-bottom:14px;text-transform:uppercase;letter-spacing:.02em;position:relative;padding-bottom:13px}
  .ses-card h3::after{content:"";position:absolute;left:50%;bottom:0;transform:translateX(-50%);width:32px;height:2px;background:var(--coral);border-radius:2px}
  .ses-card p{color:var(--ink-soft);font-size:.94rem;font-weight:400}
  .req-title{font-family:var(--serif);font-style:italic;font-size:1.25rem;color:var(--coral-d);margin-bottom:14px}
  .req-band{background:linear-gradient(180deg,rgba(255,255,255,.42),rgba(255,255,255,.26));border:1px solid rgba(255,255,255,.55);border-radius:22px;padding:30px clamp(20px,4vw,48px) 8px;margin:0 auto 34px;max-width:900px;box-shadow:0 8px 26px rgba(35,78,72,.07)}
  .req-band .req-row{margin-bottom:26px}
  .req-prose{color:var(--ink-soft);max-width:62ch;margin:0 auto 36px;font-size:1.02rem;line-height:1.6}
  .req-row{display:flex;flex-wrap:wrap;justify-content:center;gap:30px 54px;margin:0 auto 40px;max-width:780px}
  .req-item{display:flex;flex-direction:column;align-items:center;gap:11px;max-width:190px;color:var(--ink-soft);font-size:.95rem;line-height:1.35}
  .req-ico{color:var(--coral);line-height:0}
  .req-ico svg{width:34px;height:34px}
  .req-list{display:flex;flex-wrap:wrap;gap:14px 28px;margin-bottom:38px;list-style:none}
  .req-list2{list-style:none;display:flex;flex-direction:column;gap:11px;width:fit-content;margin:0 auto 36px;text-align:left}
  .req-list2 li{color:var(--ink-soft);font-size:1rem;position:relative;padding-left:26px}
  .req-list2 li::before{content:"✦";position:absolute;left:0;top:1px;color:var(--coral);font-size:.82em}
  .req-center{justify-content:center}
  .ses-sub{font-family:var(--display);font-weight:800;text-transform:uppercase;letter-spacing:-.01em;text-align:center;font-size:clamp(1.3rem,2.6vw,1.9rem);line-height:1.12;margin:6px 0 30px;color:var(--ink)}
  .ses-sub em{color:var(--coral)}
  .ses-foot{text-align:center;margin-top:50px}
  .req-list li{display:flex;align-items:center;gap:10px;color:var(--ink-soft);font-weight:500;font-size:.95rem}
  .req-list li::before{content:"→";color:var(--coral);font-weight:800}
  @media(max-width:840px){.ses-grid{grid-template-columns:1fr}.ses-card{padding:30px 20px}.ses-card + .ses-card::before{left:12%;right:12%;top:0;bottom:auto;width:auto;height:1px;background:linear-gradient(90deg,rgba(79,158,142,0),rgba(79,158,142,.26),rgba(79,158,142,0))}.ses-intro{grid-template-columns:1fr;text-align:center}.ses-head .eyebrow{justify-content:center}.ses-photo{max-width:360px;margin:0 auto}}

  /* EBOOKS */
  .ebooks h2{font-size:clamp(2.2rem,5vw,3.4rem);text-align:center;margin-bottom:12px}
  .ebooks h2 em{color:var(--coral)}
  .ebooks .lead{text-align:center;color:var(--ink-soft);max-width:46ch;margin:0 auto 54px;font-weight:400}
  .ebook-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:36px;align-items:center;max-width:900px;margin:0 auto}
  .ebook-cover .photo-ph{min-height:380px}
  .ebook-info h3{font-size:2rem;margin-bottom:8px;text-transform:none;letter-spacing:-.01em}
  .ebook-info h3 em{color:var(--coral)}
  .ebook-info .sub{font-family:var(--serif);font-style:italic;color:var(--coral-d);margin-bottom:18px;font-size:1.1rem}
  .ebook-info p{color:var(--ink-soft);font-weight:400;margin-bottom:26px}
  @media(max-width:700px){.ebook-grid{grid-template-columns:1fr}}

  /* PROGRAMAS + velo */
  .programas{background:transparent}
  .programas h2{font-size:clamp(2.2rem,5vw,3.4rem);text-align:center;margin-bottom:12px}
  .programas h2 em{color:var(--coral)}
