  @media(max-width:680px){.programas .lead{white-space:normal;max-width:42ch}}
  .prox-wrap{position:relative;max-width:940px;margin:14px auto 0;border-radius:24px;overflow:hidden}
  .prog-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;filter:blur(8px);pointer-events:none;user-select:none}
  .prog-card{background:var(--white);border:1px solid var(--line);border-radius:16px;padding:48px 32px;min-height:300px}
  .prog-card .num{font-family:var(--display);font-weight:900;color:var(--coral);font-size:1.4rem}
  .prog-card h3{font-size:1.4rem;margin:8px 0 10px;text-transform:none;letter-spacing:-.01em}
  .prog-card p{color:var(--ink-soft);font-size:.92rem;font-weight:400}
  .prox-overlay{position:absolute;inset:0;z-index:5;border-radius:24px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:15px;padding:40px 24px;background:rgba(252,253,251,.78);backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px)}
  .prox-overlay .prox-top{font-family:var(--display);font-size:.74rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--coral-d)}
  .prox-overlay .prox-big{font-family:var(--serif);font-style:italic;font-weight:400;text-transform:none;font-size:clamp(2.6rem,7vw,4.2rem);color:var(--coral-d);line-height:1}
  .prox-overlay .prox-rule{width:64px;height:3px;background:var(--fire);border-radius:3px}
  .prox-overlay .prox-chip{font-family:var(--display);font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--coral-d);border:2px solid var(--coral);border-radius:30px;padding:9px 22px}
  @media(max-width:700px){.prog-grid{grid-template-columns:1fr}}

  /* TESTIMONIOS */
  .testimonios{background:transparent}
  .testimonios.sec{padding:clamp(1.4rem,2.6vw,2.2rem) 0}
  .faq.sec{padding:clamp(1.9rem,3.6vw,3rem) 0}
  .testimonios .wrap{max-width:940px}
  .testimonios .head{text-align:center;max-width:620px;margin:0 auto 18px}
  .testimonios .head .eyebrow{justify-content:center;color:var(--coral-d)}
  .testimonios .head .eyebrow::before{background:var(--coral-d)}
  .testimonios h2{font-size:clamp(1.45rem,2.6vw,1.9rem)}
  .testimonios h2 em{color:var(--coral)}
  .testi-carousel .testi-card{flex:0 0 calc((100% - 48px)/3);box-sizing:border-box;background:rgba(255,255,255,.5);border:1px solid rgba(79,158,142,.14);border-radius:14px;padding:20px 20px;box-shadow:0 8px 24px rgba(35,78,72,.06);display:flex;flex-direction:column;text-align:left}
  .testi-card .stars{letter-spacing:.26em;color:var(--coral);margin-bottom:11px;font-size:.82rem}
  .testi-card blockquote{font-family:var(--serif);font-style:italic;font-size:.95rem;font-weight:400;line-height:1.5;color:var(--ink);margin:0 0 16px;flex:1}
  .testi-card .firma{font-family:var(--display);font-size:.7rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-d);margin:0}
  @media(max-width:840px){.testi-carousel .testi-card{flex:0 0 100%}}

  /* FAQ */
  .faq{background:transparent}
  .faq-carousel .carousel-track{align-items:flex-start}
  .faq-carousel .faq-card{flex:0 0 calc((100% - 48px)/3);box-sizing:border-box;background:rgba(255,255,255,.55);border:1px solid var(--line);border-radius:16px;padding:20px 22px;box-shadow:0 6px 20px rgba(35,78,72,.05)}
  .faq-carousel .faq-card summary{list-style:none;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;cursor:pointer;font-family:var(--display);font-weight:800;text-transform:none;letter-spacing:-.01em;font-size:1rem;line-height:1.28;color:var(--ink)}
  .faq-carousel .faq-card summary::-webkit-details-marker{display:none}
  .faq-carousel .faq-card .plus{color:var(--coral);font-size:1.35rem;line-height:1;flex-shrink:0;transition:transform .3s ease}
  .faq-carousel .faq-card[open] .plus{transform:rotate(45deg)}
  .faq-a{display:grid;grid-template-rows:0fr;transition:grid-template-rows .38s ease}
  .faq-carousel .faq-card[open] .faq-a{grid-template-rows:1fr}
  .faq-a>div{overflow:hidden}
  .faq-a p{padding-top:12px;color:var(--ink-soft);font-size:.92rem;line-height:1.55}
  @media(max-width:840px){.faq-carousel .faq-card{flex:0 0 100%}}
  .faq-carousel .faq-card{flex:0 0 calc((100% - 48px)/3);box-sizing:border-box;background:rgba(255,255,255,.5);border:1px solid rgba(79,158,142,.14);border-radius:14px;padding:20px 20px;box-shadow:0 8px 24px rgba(35,78,72,.06);display:flex;flex-direction:column;text-align:left}
  .faq-card h3{font-family:var(--display);font-weight:800;text-transform:none;letter-spacing:-.01em;font-size:1.06rem;line-height:1.25;color:var(--ink);margin-bottom:10px}
  .faq-card p{color:var(--ink-soft);font-size:.94rem;line-height:1.55}
  @media(max-width:840px){.faq-carousel .faq-card{flex:0 0 100%}}
  .faq h2{font-size:clamp(1.7rem,3.2vw,2.3rem);text-align:center;margin-bottom:22px}
  .faq h2 em{color:var(--coral)}
  .faq-list{max-width:760px;margin:0 auto}
  details{border-bottom:1px solid var(--line);padding:0}
  summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:18px;padding:13px 4px;font-size:1.06rem;font-weight:700;color:var(--ink)}
  summary::-webkit-details-marker{display:none}
  summary .plus{color:var(--coral);font-size:1.5rem;transition:transform .3s ease;flex-shrink:0}
  details[open] summary .plus{transform:rotate(45deg)}
  details p{padding:0 4px 18px;color:var(--ink-soft);font-weight:400;max-width:64ch}

  /* CTA */
  .cta{position:relative;text-align:center;color:var(--white);overflow:hidden;background:var(--ink)}
  .cta::before{content:"";position:absolute;inset:0;background:var(--fire);opacity:.92;z-index:0}
  .cta .wrap{position:relative;z-index:2}
  .cta .eyebrow{justify-content:center;color:var(--white)}
  .cta .eyebrow::before{background:var(--white)}
  .cta h2{font-size:clamp(2.6rem,6vw,4.4rem);max-width:16ch;margin:0 auto 20px}
  .cta p{color:rgba(255,255,255,.92);max-width:46ch;margin:0 auto 36px;font-weight:500}
  .cta .btn{font-size:.98rem;padding:22px 48px}
  .cta .btn-fire{background:var(--white);color:var(--coral-d);box-shadow:0 12px 30px rgba(35,78,72,.28)}
  .cta .btn-fire:hover{background:var(--ink);color:var(--white)}
  .cta .pd{margin-top:30px;font-family:var(--serif);font-style:italic;font-size:clamp(1.3rem,2.4vw,1.6rem);line-height:1.5;color:rgba(255,255,255,.95)}

  /* INVITACION */
  .invita{background:linear-gradient(180deg,#E2EDE5,#CFE3D6)}
  .invita-inner{display:flex;align-items:center;justify-content:space-between;gap:clamp(1.5rem,4vw,3rem);flex-wrap:wrap;max-width:1000px;margin:0 auto}
