  @media(max-width:640px){.invita-inner{flex-direction:column;text-align:center;align-items:center}.invita .eyebrow{justify-content:center}}

  /* FOOTER */
  footer{background:#FCFDFB;color:var(--ink-soft);padding:44px 0;text-align:center;border-top:1px solid var(--line)}
  footer .logo{font-family:var(--display);font-weight:800;text-transform:uppercase;font-size:1.2rem;color:var(--ink);margin-bottom:10px}
  footer .logo em{color:var(--coral);font-family:var(--serif);font-style:italic;text-transform:none}
  footer .social{margin:18px 0;display:flex;gap:16px;justify-content:center;align-items:center}
  footer .social a{display:inline-flex;width:44px;height:44px;align-items:center;justify-content:center;border:1px solid rgba(79,158,142,.35);border-radius:50%;color:var(--coral);transition:background .25s ease,color .25s ease,border-color .25s ease}
  footer .social a svg{width:20px;height:20px}
  footer .social a:hover{background:var(--coral);color:#fff;border-color:var(--coral)}
  footer .copy{font-size:.78rem;color:var(--ink-soft);opacity:.75;margin-top:12px}

  .reveal{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease}
  .reveal.in{opacity:1;transform:none}
  @media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}
  /* MIS SERVICIOS (selector) */
  .servicios{background:transparent}
  .servicios .serv-head{text-align:left;max-width:720px;margin:0 0 clamp(1.8rem,4vw,2.6rem)}
  .servicios .serv-head h2{font-size:clamp(2rem,4.4vw,3.1rem);white-space:nowrap;margin-bottom:16px}
  .servicios .serv-head h2 em{color:var(--coral)}
